style.css:
@-moz-document domain("outlook.office.com"), domain("outlook.live.com") {
:root {
    --pale-pink-50:  #fff6fa;
    --pale-pink-100: #ffeaf4;
    --pale-pink-200: #ffd9eb;
    --pale-pink-300: #ffc2e0; /* main pill + toolbar pink */
    --pale-pink-400: #ffaad4;
    --pale-pink-500: #ff94c9;
    --text-dark: #3a2a34;
    --white: #ffffff;
  }

  /* ? dreamy swirl background */
  html, body {
    background: radial-gradient(circle at 10% 20%, #fff6fa 0%, #ffeaf4 25%, #ffd9eb 50%, #ffc2e0 75%, #fff6fa 100%) !important;
    background-attachment: fixed !important;
    color: var(--text-dark) !important;
    font-family: "Segoe UI", sans-serif !important;
  }

  /* remove the mountain wallpaper entirely */
  [style*="background-image"], [data-automationid="App"], .ms-Fabric {
    background-image: none !important;
    background-color: transparent !important;
  }

  /* make the WHOLE toolbar match the pill pink exactly */
  [data-automationid="TopBar"], header[role="banner"], [class*="CommandBar"] {
    background: var(--pale-pink-300) !important;
    color: var(--text-dark) !important;
    border: none !important;
    box-shadow: 0 2px 6px rgba(255, 140, 200, 0.25) !important;
  }

  /* toolbar buttons: same pink tone for seamless look */
  button, [role="button"], .ms-Button {
    background: var(--pale-pink-300) !important;
    color: var(--text-dark) !important;
    border: none !important;
    border-radius: 999px !important;
    box-shadow: 0 3px 8px rgba(255, 140, 200, 0.15) !important;
    transition: all 0.25s ease-in-out !important;
  }

  button:hover, [role="button"]:hover {
    background: var(--pale-pink-400) !important;
    transform: translateY(-1px);
  }

  /* active chips / selected folders */
  [data-automationid="FolderPane"] [role="treeitem"][aria-selected="true"],
  [data-automationid="MessageList"] [aria-selected="true"],
  [data-automationid="Pivot"] [aria-selected="true"] {
    background: var(--pale-pink-300) !important;
    color: var(--text-dark) !important;
    border: none !important;
  }

  /* sidebar and message list soft translucent background */
  [data-automationid="FolderPane"],
  [data-automationid="MessageList"],
  [data-automationid="ReadingPaneContainer"] {
    background: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(8px);
    border-radius: 12px;
  }

  /* search box */
  [data-automationid="SearchBox"] input {
    background: var(--white) !important;
    border: 2px solid var(--pale-pink-300) !important;
    border-radius: 999px !important;
    color: var(--text-dark) !important;
  }

  [data-automationid="SearchBox"] input:focus {
    box-shadow: 0 0 0 3px var(--pale-pink-200) !important;
  }

  /* scrollbar */
  *::-webkit-scrollbar { width: 10px; }
  *::-webkit-scrollbar-thumb {
    background: var(--pale-pink-400);
    border-radius: 999px;
  }
  *::-webkit-scrollbar-track {
    background: var(--pale-pink-100);
  }
}
